def _search(self, searchstring):
        """ search users
        @str searchstring: search string
        @rtype: dict, {<user>: {<attr>: <value>}}
        """
        result = {}
        for user in self.users:
            if searchstring in user.name:
                result[user] = user.attr
        return result

